// Row <-> domain mappers for every table in supabase/migrations. Rules:
// - numeric columns may arrive as number or string: Number() them.
// - timestamptz -> ISO via new Date(x).toISOString(); date columns stay 'YYYY-MM-DD'.
// - null <-> optional: null DB values are omitted from domain objects; undefined domain values write null.
// - jsonb and text[] values are copied, so returned objects never share state with the database payload.
// - `properties.location` is generated by the database: never written.
import type {
  AccessibilityInfo,
  Alert,
  AlertEvent,
  AlertTarget,
  AlertTrigger,
  ApplicantProfile,
  ApplicantSensitive,
  Application,
  ApplicationDocument,
  ApplicationMember,
  ApplicationStatus,
  Building,
  BuildingKind,
  ClassYear,
  FeeQuote,
  FloorPlan,
  Group,
  GroupMember,
  Landlord,
  Landmark,
  LandmarkKind,
  Listing,
  Major,
  MajorBuildingShare,
  Photo,
  Property,
  Review,
  ReviewRatings,
  Save,
  ScheduleEntry,
  Section,
  ShortlistItem,
  Swipe,
  User,
  UserRole,
  UserSchedule,
  Vote,
  WalkTime,
  Weekday,
} from '@homed/core';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Removes keys whose value is undefined so optional fields are absent, not undefined. */
export function clean<T extends object>(obj: T): T {
  for (const k of Object.keys(obj) as (keyof T)[]) {
    if (obj[k] === undefined) delete obj[k];
  }
  return obj;
}

/** Postgres timestamptz (as PostgREST returns it) -> canonical ISO string. */
export function isoTs(x: string): string {
  return new Date(x).toISOString();
}

/** Domain optional -> DB nullable. */
function n<T>(x: T | undefined): T | null {
  return x === undefined ? null : x;
}

/** DB nullable -> domain optional. */
function o<T>(x: T | null | undefined): T | undefined {
  return x === null || x === undefined ? undefined : x;
}

function numOrUndef(x: unknown): number | undefined {
  return x === null || x === undefined ? undefined : Number(x);
}

function tsOrUndef(x: string | null): string | undefined {
  return x === null || x === undefined ? undefined : isoTs(x);
}

function dateStr(x: string): string {
  return x.slice(0, 10);
}

