// Catalog: landlords, properties, floor plans, photos, places, accessibility, walk times
// ---------------------------------------------------------------------------

export function landlordFromRow(r: LandlordRow): Landlord {
  return clean({
    id: r.id,
    userId: o(r.user_id),
    name: r.name,
    email: o(r.email),
    phone: o(r.phone),
    website: o(r.website),
    verified: r.verified,
    createdAt: isoTs(r.created_at),
  });
}

export function landlordToRow(l: Landlord): LandlordRow {
  return {
    id: l.id,
    user_id: n(l.userId),
    name: l.name,
    email: n(l.email),
    phone: n(l.phone),
    website: n(l.website),
    verified: l.verified,
    created_at: l.createdAt,
  };
}

export function propertyFromRow(r: PropertyRow): Property {
  return clean({
    id: r.id,
    slug: r.slug,
    name: r.name,
    address: r.address,
    location: { lat: Number(r.lat), lng: Number(r.lng) },
    kind: r.kind,
    onGrounds: r.on_grounds,
    neighborhood: r.neighborhood,
    yearBuilt: numOrUndef(r.year_built),
    yearRenovated: numOrUndef(r.year_renovated),
    landlordId: o(r.landlord_id),
    website: o(r.website),
    amenities: structuredClone(r.amenities),
    noiseLevel: o(r.noise_level),
    litRouteToGrounds: o(r.lit_route_to_grounds),
    onBusRoute: r.on_bus_route,
    busRoutes: [...r.bus_routes],
    studyAbroadFriendly: r.study_abroad_friendly,
    noGuarantorOption: r.no_guarantor_option,
    gradHeavy: o(r.grad_heavy),
    onGroundsInfo: r.on_grounds_info === null ? undefined : structuredClone(r.on_grounds_info),
    source: r.source,
    dataStatus: r.data_status,
    lastVerified: dateStr(r.last_verified),
  });
}

/** `location` is never written: the database derives it from lat/lng. */
export function propertyToRow(p: Property): PropertyRow {
  return {
    id: p.id,
    slug: p.slug,
    name: p.name,
    address: p.address,
    lat: p.location.lat,
    lng: p.location.lng,
    kind: p.kind,
    on_grounds: p.onGrounds,
    neighborhood: p.neighborhood,
    year_built: n(p.yearBuilt),
    year_renovated: n(p.yearRenovated),
    landlord_id: n(p.landlordId),
    website: n(p.website),
    amenities: structuredClone(p.amenities),
    noise_level: n(p.noiseLevel),
    lit_route_to_grounds: n(p.litRouteToGrounds),
    on_bus_route: p.onBusRoute,
    bus_routes: [...p.busRoutes],
    study_abroad_friendly: p.studyAbroadFriendly,
    no_guarantor_option: p.noGuarantorOption,
    grad_heavy: n(p.gradHeavy),
    on_grounds_info: p.onGroundsInfo ? structuredClone(p.onGroundsInfo) : null,
    source: p.source,
    data_status: p.dataStatus,
    last_verified: p.lastVerified,
  };
}

export function floorPlanFromRow(r: FloorPlanRow): FloorPlan {
  return clean({
    id: r.id,
    propertyId: r.property_id,
    name: r.name,
    beds: Number(r.beds),
    baths: Number(r.baths),
    sqft: numOrUndef(r.sqft),
    rentAmount: Number(r.rent_amount),
    rentBasis: r.rent_basis,
    leaseStart: dateStr(r.lease_start),
    leaseEnd: dateStr(r.lease_end),
    termKind: r.term_kind,
    leaseType: r.lease_type,
    furnished: r.furnished,
    furnitureMonthly: numOrUndef(r.furniture_monthly),
    utilitiesIncluded: r.utilities_included,
    utilitiesEstimate: numOrUndef(r.utilities_estimate),
    internetIncluded: r.internet_included,
    internetEstimate: numOrUndef(r.internet_estimate),
    inUnitLaundry: r.in_unit_laundry,
    dishwasher: r.dishwasher,
    ac: r.ac,
    // Nullable by contract (unknown availability), so null stays null.
    unitsAvailable: r.units_available === null ? null : Number(r.units_available),
    totalUnits: numOrUndef(r.total_units),
    applicationFee: numOrUndef(r.application_fee),
    screeningCost: numOrUndef(r.screening_cost),
    applicationDeposit: numOrUndef(r.application_deposit),
    securityDeposit: numOrUndef(r.security_deposit),
    floorPlanImageUrl: o(r.floor_plan_image_url),
    lastVerified: dateStr(r.last_verified),
  });
}

export function floorPlanToRow(f: FloorPlan): FloorPlanRow {
  return {
    id: f.id,
    property_id: f.propertyId,
    name: f.name,
    beds: f.beds,
    baths: f.baths,
    sqft: n(f.sqft),
    rent_amount: f.rentAmount,
    rent_basis: f.rentBasis,
    lease_start: f.leaseStart,
    lease_end: f.leaseEnd,
    term_kind: f.termKind,
    lease_type: f.leaseType,
    furnished: f.furnished,
    furniture_monthly: n(f.furnitureMonthly),
    utilities_included: f.utilitiesIncluded,
    utilities_estimate: n(f.utilitiesEstimate),
    internet_included: f.internetIncluded,
    internet_estimate: n(f.internetEstimate),
    in_unit_laundry: f.inUnitLaundry,
    dishwasher: f.dishwasher,
    ac: f.ac,
    units_available: f.unitsAvailable,
    total_units: n(f.totalUnits),
    application_fee: n(f.applicationFee),
    screening_cost: n(f.screeningCost),
    application_deposit: n(f.applicationDeposit),
    security_deposit: n(f.securityDeposit),
    floor_plan_image_url: n(f.floorPlanImageUrl),
    last_verified: f.lastVerified,
  };
}

