/** Major.buildings comes from the major_buildings rows, passed in. */
export function majorFromRow(r: MajorRow, buildings: MajorBuildingRow[]): Major {
  return {
    id: r.id,
    name: r.name,
    school: r.school,
    buildings: buildings
      .filter((b) => b.major_id === r.id)
      .map((b): MajorBuildingShare => ({ buildingId: b.building_id, share: Number(b.share) })),
    meetingsPerWeek: Number(r.meetings_per_week),
  };
}

export function majorToRow(m: Major): MajorRow {
  return { id: m.id, name: m.name, school: m.school, meetings_per_week: m.meetingsPerWeek };
}

/** Rows for the major_buildings join table. */
export function majorBuildingRows(m: Major): MajorBuildingRow[] {
  return m.buildings.map((b) => ({ major_id: m.id, building_id: b.buildingId, share: b.share }));
}

